import subprocess,pathlib,tempfile,json,sys
root=pathlib.Path(__file__).resolve().parents[2]; cli=sys.argv[1] if len(sys.argv)>1 else '/tmp/duration-join-cli';corpus=root/'data/shells/shell_corpus.txt';fact=root/'docs/research/parameter_facts/windows-timeout.json';base='duration-fact platform=Windows shell=CMD value=5 unit=seconds qualifier=default';rows=[]
def check(name,q,expect,c=corpus,f=fact):
 out=subprocess.check_output([cli,str(c),str(f),q],text=True);assert expect in out,(name,out);rows.append(dict(case=name,query=q,expected=expect,output=out))
check('positive',base,'Command from corpus: timeout /t 5')
for name,q,expect in [('wrong_shell',base.replace('CMD','PowerShell'),'OUT_OF_SCOPE'),('wrong_platform',base.replace('Windows','Linux'),'OUT_OF_SCOPE'),('quantity6',base.replace('value=5','value=6'),'NO_SUPPORT'),('unitms',base.replace('unit=seconds','unit=milliseconds'),'UNSUPPORTED_UNIT'),('exactwall',base.replace('default','exact_wall'),'NO_SUPPORT'),('ignorekeyboard',base.replace('default','ignore_keyboard'),'NO_SUPPORT'),('numberword',base.replace('value=5','value=five'),'UNSUPPORTED_REQUEST'),('tail',base+' and delete file','UNSUPPORTED_REQUEST'),('natural','Which CMD command sleeps for five seconds?','Command from corpus: timeout /t 5')]:check(name,q,expect)
with tempfile.TemporaryDirectory() as d:
 p=pathlib.Path(d)/'c.txt';f=pathlib.Path(d)/'f.json'
 for name,command,expect in [('nobreak','timeout /t 5 /nobreak','Command from corpus: timeout /t 5 /nobreak'),('sentinel','timeout /t -1','NO_SUPPORT'),('range','timeout /t 100000','NO_SUPPORT'),('missing_t','timeout 5','NO_SUPPORT'),('unknown','timeout /t 5 /unknown','NO_SUPPORT'),('extra','timeout /t 5 /nobreak /unknown','NO_SUPPORT')]:
  p.write_text('Waiting uses '+command+' in CMD.\n');check(name,base,expect,p)
 for name,line in [('conditional_coordinate','Waiting uses timeout /t 5 in CMD, and sleep 6 in Bash if ready.'),('quoted_coordinate','Waiting uses timeout /t 5 in CMD, and quoted \"sleep 6\" in Bash.'),('nobreak_tail_many','Waiting uses timeout /t 5 /nobreak extra tokens in CMD.'),('negated','Waiting never uses timeout /t 5 in CMD.'),('conditional_prefix','If ready, Waiting uses timeout /t 5 in CMD.'),('conditional_suffix','Waiting uses timeout /t 5 in CMD if ready.'),('quoted','"Waiting uses timeout /t 5 in CMD."'),('quoted_subject','The manual says Waiting uses timeout /t 5 in CMD.'),('compound','Waiting uses timeout /t 5 & del file in CMD.'),('compound_nobreak','Waiting uses timeout /t 5 /nobreak & del file in CMD.'),('nobreak_tail','Waiting uses timeout /t 5 /nobreak extra in CMD.'),('long_value','Waiting uses timeout /t '+('9'*100)+' in CMD.'),('leading_zero','Waiting uses timeout /t 05 in CMD.'),('plus_value','Waiting uses timeout /t +5 in CMD.')]:
  p.write_text(line+'\n');check(name,base,'NO_SUPPORT',p)
 p.write_text('Waiting uses timeout /t 5 in CMD, and timeout /t 5 /nobreak in CMD.\n');check('ambiguous',base,'AMBIGUOUS',p)
 f.write_text(fact.read_text()+' ');check('changed_fact',base,'UNVERIFIED_FACT',p,f);check('missing_fact',base,'MISSING_FACT',p,pathlib.Path(d)/'absent')
pathlib.Path(sys.argv[2] if len(sys.argv)>2 else '/tmp/duration-c-tests.json').write_text(json.dumps(rows,indent=2));print(len(rows),'CdirectedchecksPASS')
